/bin/zsh -lc "python3 -c 'import csv,datetime as d,collections as c,ipaddress; f=open(\"Semana12/logs_sinteticos.csv\",newline=\"\"); reader=csv.DictReader(f); rows=[(n,r,d.datetime.fromisoformat(r[\"timestamp\"])) for n,r in enumerate(reader,2)]; [ipaddress.ip_address(r[\"ip\"]) for n,r,t in rows]; print(\"Validacion:\",len(rows),\"registros; timestamps ISO con zona; IP validas; campos textuales completos:\",all(all(isinstance(v,str) and v for v in r.values()) for n,r,t in rows)); print(\"Orden original cronologico:\",all(rows[i][2]<=rows[i+1][2] for i in range(len(rows)-1))); rows.sort(key=lambda x:x[2]); dup=c.defaultdict(list); [dup[tuple(r.items())].append(n) for n,r,t in rows]; print(\"Grupos de filas identicas:\",[ns for ns in dup.values() if len(ns)>1]); print(\"Conteos evento/resultado:\",dict(c.Counter((r[\"event\"],r[\"result\"]) for n,r,t in rows))); fails=[x for x in rows if x[1][\"event\"]==\"login\" and x[1][\"result\"]==\"failed\"]; brute={}; spray={};
for n,r,t in fails:
 w=[x for x in fails if t<=x[2]<=t+d.timedelta(minutes=5) and x[1][\"ip\"]==r[\"ip\"]]; b=[x for x in w if x[1][\"user\"]==r[\"user\"]]; key=(r[\"ip\"],r[\"user\"])
 if len(b)>=6 and (key not in brute or len(b)>len(brute[key])): brute[key]=b
 if len(set(x[1][\"user\"] for x in w))>=5 and (r[\"ip\"] not in spray or len(w)>len(spray[r[\"ip\"]])): spray[r[\"ip\"]]=w
for key,w in brute.items():
 print(\"Fuerza bruta:\",key,\"filas\",[x[0] for x in w],\"inicio\",w[0][2].isoformat(),\"fin\",w[-1][2].isoformat()); print(\"Exitos posteriores <=5min:\",[n for n,r,t in rows if r[\"event\"]==\"login\" and r[\"result\"]==\"success\" and (r[\"ip\"],r[\"user\"])==key and w[-1][2]<t<=w[-1][2]+d.timedelta(minutes=5)])
for ip,w in spray.items(): print(\"Spraying:\",ip,\"filas\",[x[0] for x in w],\"usuarios\",sorted(set(x[1][\"user\"] for x in w)))'"

